findings.fix:
block_device_mappings {
  device_name = "/dev/sdb"
  ebs {
    encrypted   = true
    volume_size = 80
    volume_type = "gp3"
  }
}

data "aws_default_tags" "current" {}

dynamic "tag" {
  for_each = merge(data.aws_default_tags.current.tags, { Name = var.name })
  content {
    key                 = tag.key
    value               = tag.value
    propagate_at_launch = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0, < 7.0"
    }
  }
  required_version = ">= 1.5.0"
}
